/** Websocket / DTO helpers for Family Tree. */

import type { HomeAssistant } from "./types";

export interface LifeEventDto {
  type: "birth" | "death" | "marriage" | string;
  sort_date: string | null;
  date_text?: string;
  date_qualifier?: string;
  place_id: string | null;
  place_name: string | null;
}

export interface PersonRef {
  id: string;
  name: string;
}

export interface VitalSummary {
  type: string;
  date_text: string;
  date_qualifier: string;
  sort_date: string | null;
  place_name: string | null;
}

export interface LineageRelation {
  type: "ancestor" | "descendant";
  generation: number;
}

export interface MyLineageDto {
  person_id: string | null;
  person_name: string | null;
  relatives: Record<string, LineageRelation>;
}

export interface PersonDto {
  id: string;
  given_names: string;
  call_name: string;
  surname_prefix: string;
  surname: string;
  sex: string;
  is_living: boolean;
  notes: string;
  display_name?: string;
  created_at?: string;
  updated_at?: string;
  deleted_at?: string | null;
  /** Present on persons/list for client-side place/date filters. */
  life_events?: LifeEventDto[];
  /** persons/list overview columns. */
  father?: PersonRef | null;
  mother?: PersonRef | null;
  children_count?: number;
  birth?: VitalSummary | null;
  death?: VitalSummary | null;
  profile_media_id?: string | null;
  profile_source_media_id?: string | null;
  profile_crop?: ProfileCropDto | null;
}

export interface ProfileCropDto {
  scale: number;
  offsetX: number;
  offsetY: number;
}

export interface PersonMediaDto {
  id: string;
  person_id: string;
  content_type: string;
  original_filename: string;
  caption: string;
  byte_size: number;
  width: number | null;
  height: number | null;
  sort_order: number;
  source_url: string;
  created_at: string;
  updated_at: string;
}

export interface EventDto {
  id: string;
  subject_type: string;
  subject_id: string;
  type: string;
  place_id: string | null;
  date_text: string;
  date_qualifier: string;
  date_from: string | null;
  date_to: string | null;
  sort_date: string | null;
  description: string;
  place_name?: string;
  union_id?: string;
  partner_names?: string[];
  related_person_id?: string;
  related_person_name?: string;
  relation?: "child" | "partner";
}

export interface PlaceDto {
  id: string;
  name: string;
  admin1: string;
  country: string;
  country_code: string;
  latitude: number | null;
  longitude: number | null;
  geonames_id: number | null;
}

export interface UnionDto {
  id: string;
  type: string;
  status: string;
  known_children_count: number | null;
  notes: string;
}

export interface StatsDto {
  total_persons: number;
  living: number;
  deceased: number;
  ages: { labels: string[]; values: number[] };
  centuries: { labels: string[]; values: number[] };
  places_of_birth: { labels: string[]; values: number[] };
}

export interface SettingsDto {
  name: string;
  gazetteer_countries: string[];
  family_shortcuts: string[];
  can_write: boolean;
  upcoming_birthdays: Array<Record<string, unknown>>;
  upcoming_anniversaries: Array<Record<string, unknown>>;
  on_this_day?: Array<Record<string, unknown>>;
}

export interface PersonDetail {
  person: PersonDto;
  events: EventDto[];
  citations: Array<Record<string, unknown>>;
  tree: TreePayload | null;
}

export interface TreeUnion {
  union_id: string;
  type: string;
  status: string;
  known_children_count: number | null;
  partners: Array<Record<string, unknown>>;
  children: Array<Record<string, unknown>>;
  marriage_date: string;
  marriage_place: string;
  divorce_date: string;
  divorce_place: string;
}

export interface TreePayload {
  person: PersonDto & {
    name?: string;
    sibling_count?: number;
    children_count?: number;
    has_parent?: boolean;
  };
  parents: Array<Record<string, unknown>>;
  grandparents: Record<string, Array<Record<string, unknown>>>;
  partners: TreeUnion[];
  children: Array<Record<string, unknown>>;
  children_without_union?: Array<Record<string, unknown>>;
  siblings: Array<Record<string, unknown>>;
}

export interface GazetteerHit {
  geonames_id: number;
  name: string;
  asciiname: string;
  country_code: string;
  admin1_code: string;
  admin1: string;
  latitude: number | null;
  longitude: number | null;
  population: number;
}

function msg(
  hass: HomeAssistant,
  type: string,
  extra: Record<string, unknown> = {},
): Promise<unknown> {
  return hass.connection.sendMessagePromise({ type, ...extra });
}

export async function getRevision(hass: HomeAssistant): Promise<{ revision: number }> {
  return msg(hass, "family_tree/revision") as Promise<{ revision: number }>;
}

export async function subscribeRevision(
  hass: HomeAssistant,
  callback: (data: { revision: number }) => void,
): Promise<() => void> {
  return hass.connection.subscribeMessage<{ revision: number }>(callback, {
    type: "family_tree/subscribe",
  });
}

