export function personMediaUploadUrl(
  personId: string,
  _hass?: HomeAssistant,
  query?: Record<string, string>,
): string {
  const params = new URLSearchParams(query);
  const qs = params.toString();
  return `/api/family_tree/persons/${personId}/media${qs ? `?${qs}` : ""}`;
}

